    if (newLength > buffer.length) {
        int newCapacity = Math.max(buffer.length * 2, newLength);
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(buffer, 0, newBuffer, 0, this.length);
        buffer = newBuffer;
    }
    // Copy bytes
    if (byteArrayValue != null) {
        System.arraycopy(byteArrayValue, byteOffset, buffer, this.length, byteLength);
    } else {
        // fill with null bytes (0)
        for (int i = 0; i < byteLength; i++) {
            buffer[this.length + i] = 0;
        }
    }
    this.length = newLength;
